<?php
// phpcs:ignoreFile -- runs before Magento boots, so it must require, include and exit directly.
// Usage: php registration-manifest.php <magento root>. Run by preload:build in its own process, because
// registering a component twice throws. Replaces the ~400 registration.php files composer includes on
// every request with one generated file. composer dump-autoload undoes it.
$bp = $argv[1];
$static = file_get_contents("$bp/vendor/composer/autoload_static.php");
if (str_contains($static, "'samjuk-perf-registrations'")) {
    exit("already applied\n");
}
preg_match('/class (ComposerStaticInit\w+)/', $static, $m);
$class = 'Composer\\Autoload\\' . $m[1];

require "$bp/vendor/composer/ClassLoader.php";
require "$bp/vendor/composer/autoload_static.php";
$loader = new Composer\Autoload\ClassLoader("$bp/vendor");
$class::getInitializer($loader)();
$loader->register();

use Magento\Framework\Component\ComponentRegistrar as R;

// Only files that do nothing but ComponentRegistrar::register() can be replaced; anything else stays.
$onlyRegisters = static function (string $file): bool {
    $code = php_strip_whitespace($file);
    $code = preg_replace('/\\\\?(Magento\\\\Framework\\\\Component\\\\)?ComponentRegistrar::register\s*\((?:[^()]|\((?:[^()]|\([^()]*\))*\))*\)\s*;/s', '', $code);
    $code = preg_replace('/^<\?php|use [^;]+;|namespace [^;]+;|declare\([^)]*\);/', '', $code);
    return trim($code) === '';
};
$keep = static fn (string $f) => !str_ends_with($f, '/registration.php') || !$onlyRegisters($f);

$types = [R::MODULE, R::THEME, R::LANGUAGE, R::LIBRARY, R::SETUP];
$snapshot = static fn () => array_merge(...array_map(static fn ($t) => array_map(static fn ($p) => [$t, $p], (new R())->getPaths($t)), $types));

$out = "<?php\n// Generated by samjuk/m2-module-performance preload:build\nuse Magento\\Framework\\Component\\ComponentRegistrar as R;\n";
$removed = [];
foreach ($class::$files as $hash => $file) {
    if ($keep($file)) {
        require_once $file;
        continue;
    }
    $before = $snapshot();
    require $file;
    foreach (array_diff_key($snapshot(), $before) as $name => [$type, $path]) {
        $out .= 'R::register(' . var_export($type, true) . ', ' . var_export($name, true) . ', ' . var_export($path, true) . ");\n";
    }
    $removed[$hash] = true;
}
file_put_contents("$bp/vendor/composer/autoload_registrations.php", $out);

$static = preg_replace_callback('/public static \$files = array \((.*?)\n    \);/s', static function ($block) use ($removed) {
    $lines = array_filter(explode("\n", $block[1]), static function ($line) use ($removed) {
        return !preg_match("/^\s*'(\w+)' => /", $line, $p) || !isset($removed[$p[1]]);
    });
    $lines[] = "        'samjuk-perf-registrations' => __DIR__ . '/autoload_registrations.php',";
    return "public static \$files = array (" . implode("\n", $lines) . "\n    );";
}, $static, 1, $count);
$count === 1 || exit("could not find \$files in autoload_static.php\n");
file_put_contents("$bp/vendor/composer/autoload_static.php", $static);

// Skip re-requiring autoload_static.php when opcache.preload already declared it.
$real = file_get_contents("$bp/vendor/composer/autoload_real.php");
$real = str_replace(
    "        require __DIR__ . '/autoload_static.php';",
    "        class_exists(\\$class::class, false) || require __DIR__ . '/autoload_static.php';",
    $real
);
file_put_contents("$bp/vendor/composer/autoload_real.php", $real);

echo count($removed) . ' registration.php includes replaced, ' . substr_count($out, 'R::register') . " registrations\n";
